package br.com.mecaniQA.api.Mappers;
import java.sql.*; import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Enums.*;
public class PecasResultSetMapper implements ResultSetMapper<Pecas>{public Pecas map(ResultSet r)throws SQLException{String c=r.getString("categoria_peca");Pecas x=new Pecas(r.getString("nome"),r.getString("fornecedor_marca"),r.getInt("quantidade_estoque"),r.getString("codigo_de_barras"),r.getDouble("preco_custo"),r.getDouble("preco_venda"),c==null?null:CategoriaPeca.valueOf(c));x.setCodigoUnico(r.getLong("codigo_unico"));Object n=r.getObject("tamanho");x.setTamanho(n==null?null:((Number)n).doubleValue());x.setCor(r.getString("cor"));Timestamp t=r.getTimestamp("data_atualizacao");x.setDataAtualizacao(t==null?null:t.toLocalDateTime());return x;}}
